requester.send_request = function (urls,callback) {
    //console.log(urls)
  var req = function (url,callback) {
      request(url,function (e,o) {
			o = JSON.parse(o.body);
			if (o.status === 'ERROR') {
				callback(o.status,o.error_message);
			} else {
				callback(e,o);
			}
		});
  }
	if (Array.isArray(urls)){
		async.map(urls, req, function (e,r) {
			callback(e,r);
		});
	} else {
		req(urls,callback);
	}

}
